// Ordinary phone panels avoid native dialog differences in iOS Safari.
const mobileSurfaces=new Map();
function openSurface(id){
 const dialog=$('#'+id);
 if(!matchMedia('(max-width:700px)').matches){if(!dialog.open)dialog.showModal();return;}
 if(mobileSurfaces.has(id))return;
 const panel=el('div','mobile-dialog');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');
 const content=el('div','mobile-dialog-content');content.append(...dialog.childNodes);panel.append(content);
 const heading=content.querySelector('h2');if(heading){if(!heading.id)heading.id=id+'-heading';panel.setAttribute('aria-labelledby',heading.id);}
 const focused=document.activeElement;const backgrounds=[...document.body.children].map(node=>[node,node.inert]);
 for(const [node]of backgrounds)node.inert=true;
 mobileSurfaces.set(id,{panel,content,focused,backgrounds,overflow:document.body.style.overflow});
 document.body.style.overflow='hidden';document.body.append(panel);
 panel.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();closeSurface(id);}if(event.key==='Tab'){const controls=[...content.querySelectorAll('button:not(:disabled),a[href],input,textarea')].filter(node=>node.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
 content.querySelector('[data-close]')?.focus({preventScroll:true});
}
function closeSurface(id){
 const surface=mobileSurfaces.get(id);const dialog=$('#'+id);
 if(!surface){dialog.close();return;}
 dialog.append(...surface.content.childNodes);surface.panel.remove();mobileSurfaces.delete(id);
 for(const [node,inert]of surface.backgrounds)node.inert=inert;
 document.body.style.overflow=surface.overflow;dialog.dispatchEvent(new Event('close'));
 if(surface.focused?.isConnected)surface.focused.focus({preventScroll:true});
}
