function photosAllowed(){return !!state.me?.plus||(state.me?.americanStatus==='verified'&&Date.now()-Date.parse(state.me.americanVerification?.checkedAt)<90*86400000);}
function updateComposerPlan(){const plus=!!state.me?.plus;const photos=photosAllowed();$('#post-images').disabled=!photos||uploadingMedia;$('#post-video').disabled=!plus||uploadingMedia;$('#media-upgrade').classList.toggle('hidden',plus);$('#media-upgrade').textContent=photos?'Unlock videos with Plus ↗':'Unlock photos and videos with Plus ↗';$('#media-verify').classList.toggle('hidden',photos);$('#char-count').textContent=[...segmenter.segment($('#post-text').value)].length+' / '+(plus?833:300);if(pendingMedia.some(m=>m.mime==='video/mp4'?!plus:!photos))clearMedia();}
function renderMediaPreview(){const panel=$('#media-preview');panel.replaceChildren();for(const m of pendingMedia){const card=el('div','attachment-preview');const preview=el(m.mime==='video/mp4'?'video':'img');preview.src=m.preview;if(m.mime==='video/mp4'){preview.controls=true;preview.preload='metadata';}else preview.alt='Your image attachment';const label=el('label','','Description (optional)');const alt=el('textarea');alt.maxLength=2000;alt.value=m.alt;alt.oninput=()=>m.alt=alt.value;label.append(alt);const remove=el('button','text-button','Remove');remove.type='button';remove.disabled=uploadingMedia;remove.onclick=()=>{pendingMedia=pendingMedia.filter(x=>x!==m);URL.revokeObjectURL(m.preview);renderMediaPreview();};card.append(preview,label,remove);panel.append(card);}}
function preparePostPhoto(file){if(file.size>250000000)throw Error('Photos must be at most 250 MB (0.25 GB) each.');const extension=file.name.split('.').pop().toLowerCase();const formats={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',heif:'image/heif'};const mime=formats[extension]||file.type;if(!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(mime))throw Error('Choose JPEG, PNG, WebP or iPhone HEIC/HEIF photos.');return file.slice(0,file.size,mime);}
async function uploadSelected(files,video=false){if(!requireMe())return;if(video?!state.me.plus:!photosAllowed()){navigate(video?'plus':'account');return;}if(uploadingMedia){toast('Wait for the current uploads to finish.');return;}if(!files.length)return;if(video?(pendingMedia.length||files.length!==1):(pendingMedia.some(m=>m.mime==='video/mp4')||pendingMedia.length+files.length>4)){toast('Attach up to four images or one video.');return;}uploadingMedia=true;$('#composer button[type=submit]').disabled=true;$('#post-images').disabled=true;$('#post-video').disabled=true;renderMediaPreview();try{for(const file of files){$('#media-status').textContent='Uploading '+file.name+'…';const videoMime=file.type==='video/quicktime'||/\.mov$/i.test(file.name)?'video/quicktime':'video/mp4';if(video&&(!['video/mp4','video/quicktime'].includes(file.type)&&! /\.(mp4|mov)$/i.test(file.name)||file.size>250000000))throw Error('Choose an MP4 or iPhone MOV video under 250 MB (0.25 GB) and no longer than 3 minutes.');const blob=video?file:preparePostPhoto(file);const response=await fetch('/api/media/upload',{method:'POST',headers:{Authorization:'Bearer '+state.token,'Content-Type':video?videoMime:blob.type},body:blob});const result=await response.json();if(!response.ok)throw Error(result.error||'Media upload failed.');pendingMedia.push({...result,alt:'',preview:result.preview||URL.createObjectURL(blob)});renderMediaPreview();}$('#media-status').textContent='Attachments ready.';}catch(e){$('#media-status').textContent=e.message;}finally{uploadingMedia=false;$('#composer button[type=submit]').disabled=false;updateComposerPlan();$('#post-images').value='';$('#post-video').value='';renderMediaPreview();}}
