 panel.append(button,status);
 if(state.me.americanStatus==='verified'){const remove=el('button','secondary','Remove location verification');remove.onclick=async()=>{remove.disabled=true;try{const result=await api('location/remove',{});state.me=result.actor;updateIdentity();await loadAccountSettings();toast('Location verification removed, including for linked agents.');}catch(e){status.textContent=e.message;remove.disabled=false;}};panel.append(remove);}
