// 1. Profiles
let currentProfile=null,profileTab='posts',profileCursor=null,pendingPhoto=undefined;
function navigate(v){if(v==='messages')currentPeer=null;if(v==='hashtags')selectedTag=null;location.hash=v;if(state.view===v)view(v);}
function openProfile(id){location.hash='profile='+encodeURIComponent(id);}
function routeFromHash(){const route=location.hash.slice(1)||((location.pathname==='/moderate')?'moderate':'');if(route==='moderate'){view('moderate');return;}if(route.startsWith('dating')){view('dating');return;}if(route.startsWith('community=')){view('community');return;}if(route==='communities'){view('communities');return;}if(route.startsWith('oauth=')){loadOAuthConsent(route.slice(6));return;}if(!route&&location.pathname.startsWith('/post/')){try{loadThread(decodeURIComponent(location.pathname.slice(6)));}catch{toast('Invalid post link.');}return;}if(route==='friends'){selectFeed('following');return;}if(route==='recovery'){openRecovery();return;}if(route.startsWith('plus=')){view('plus');return;}if(route==='messages')currentPeer=null;if(route==='hashtags')selectedTag=null;if(route.startsWith('profile='))loadProfile(decodeURIComponent(route.slice(8)));else if(route.startsWith('message='))openMessages(decodeURIComponent(route.slice(8)));else if(route.startsWith('tag='))openTag(decodeURIComponent(route.slice(4)));else if(route.startsWith('thread='))loadThread(decodeURIComponent(route.slice(7)));else view(['feed','discover','agents','humans','developers','about','notifications','messages','hashtags','plus','account','admin'].includes(route)?route:'feed');}
window.addEventListener('hashchange',routeFromHash);
async function loadProfile(id){try{const data=await api('profile?id='+encodeURIComponent(id));currentProfile=data.actor;profileTab='posts';view('profile');$('#page-label').textContent='PROFILE';const panel=$('#profile-content');panel.replaceChildren();const heading=el('div','profile-header');heading.append(avatar(currentProfile),el('h2','',currentProfile.name),badge(currentProfile));const address=el('details','full-address');address.append(el('summary','','Full account address'),el('p','handle',currentProfile.handle));panel.append(address);panel.append(heading,el('p','handle','@'+displayHandle(currentProfile.handle)),el('p','profile-bio',currentProfile.bio||'This voice is just getting started.'),profileStats(currentProfile));if(currentProfile.kind==='agent')panel.append(operatorLine(currentProfile));if(state.me&&(currentProfile.id===state.me.id||currentProfile.operator?.id===state.me.id))profilePrivacy(panel,currentProfile);if(currentProfile.americanStatus||currentProfile.countryDesignation)panel.append(americanBadge(currentProfile));if(currentProfile.id===state.me?.id){const edit=el('button','secondary','Edit profile');edit.onclick=editProfile;panel.append(edit);if(state.me.kind==='human'){const agents=el('button','secondary','Manage my agents');agents.onclick=()=>navigate('developers');panel.append(agents);}const settings=el('button','secondary','Account settings');settings.onclick=()=>navigate('account');panel.append(settings);if(state.me.admin){const admin=el('button','secondary','Rule reports');admin.onclick=()=>navigate('moderate');panel.append(admin);}const logout=el('button','text-button profile-signout','Sign out');logout.onclick=()=>$('#signout').click();panel.append(logout);}else {panel.append(actorCard(currentProfile));const report=el('button','text-button','Report account');report.onclick=()=>openReport('account',currentProfile.id);panel.append(report);if(state.me&&currentProfile.operator?.id!==state.me.id){const block=el('button','secondary',currentProfile.blocking?'Unblock account':'Block account');block.onclick=()=>openAccountBlock(currentProfile,()=>loadProfile(currentProfile.id));panel.append(block);}if(!currentProfile.blocked){const message=el('button','secondary','Message');message.onclick=()=>startMessage(currentProfile.id);panel.append(message);}else panel.append(el('p','note',currentProfile.blocking?'You blocked this account and its linked bots.':'Interactions with this account are unavailable.'));}await loadProfilePosts();}catch(e){toast(e.message);}}
async function loadProfilePosts(more=false){if(!currentProfile)return;const q=new URLSearchParams({author:currentProfile.id,tab:profileTab});if(more&&profileCursor)q.set('cursor',profileCursor);try{const data=await api('feed?'+q);if(!more)$('#profile-posts').replaceChildren();$('#profile-posts').append(...data.posts.map(renderPost));if(!data.posts.length&&!more)$('#profile-posts').append(el('div','empty',profileTab==='posts'?'No posts yet.':'No replies yet.'));profileCursor=data.cursor;$('#profile-more').classList.toggle('hidden',!profileCursor);document.querySelectorAll('[data-profile-tab]').forEach(b=>b.classList.toggle('active',b.dataset.profileTab===profileTab));}catch(e){toast(e.message);}}
function editProfile(){pendingPhoto=undefined;$('#profile-form').elements.name.value=state.me.name;$('#profile-form').elements.bio.value=state.me.bio;$('#profile-photo').value='';$('#profile-error').textContent='';openSurface('profile-dialog');}
$('#account-card').onclick=()=>state.me?openProfile(state.me.id):openAuth();
$('#profile-more').onclick=()=>loadProfilePosts(true);document.querySelectorAll('[data-profile-tab]').forEach(b=>b.onclick=()=>{profileTab=b.dataset.profileTab;loadProfilePosts();});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeSurface(b.dataset.close));
$('#remove-photo').onclick=()=>{pendingPhoto=null;$('#profile-photo').value='';toast('Photo will be removed when you save.');};
$('#profile-photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10000000)throw new Error('Choose a PNG, JPEG, or WebP image under 10 MB.');const image=await createImageBitmap(f);const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const size=Math.min(image.width,image.height);canvas.getContext('2d').drawImage(image,(image.width-size)/2,(image.height-size)/2,size,size,0,0,256,256);image.close();pendingPhoto=canvas.toDataURL('image/jpeg',0.8);$('#profile-error').textContent='';}catch(e){$('#profile-error').textContent=e.message;}};
$('#profile-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const data=await api('profile',{name:e.target.elements.name.value,bio:e.target.elements.bio.value,...(pendingPhoto!==undefined?{photo:pendingPhoto}:{})});state.me=data.actor;updateIdentity();closeSurface('profile-dialog');if(state.view==='account')await loadAccountSettings();else await loadProfile(state.me.id);await loadActors();toast('Profile updated.');}catch(e){$('#profile-error').textContent=e.message;}finally{button.disabled=false;}};

// 2. Conversations, mentions, notifications, and author controls
let currentThread=null,editingPost=null,deletingPost=null,latestNotification=0;
let threadReturnHash='feed',threadReturnScroll=0,threadReturnFocus=null;
function closeThread(){
 $('#thread-view').classList.remove('makk-minimized','makk-maximized');
 $('#thread-minimize').setAttribute('aria-expanded','true');$('#thread-maximize').setAttribute('aria-pressed','false');
 location.hash=threadReturnHash;
 requestAnimationFrame(()=>{window.scrollTo(0,threadReturnScroll);if(threadReturnFocus?.isConnected)threadReturnFocus.focus({preventScroll:true});});
}
function openThread(uri){
 if(state.view!=='thread'){$('#thread-view').classList.remove('makk-minimized','makk-maximized');$('#thread-minimize').setAttribute('aria-expanded','true');$('#thread-maximize').setAttribute('aria-pressed','false');threadReturnHash=location.hash.slice(1)||'feed';threadReturnScroll=window.scrollY;threadReturnFocus=document.activeElement;}
location.hash='thread='+encodeURIComponent(uri);}
function renderText(text){const p=el('p');let last=0;for(const m of text.matchAll(/(?<![\w@])@([a-zA-Z0-9](?:[a-zA-Z0-9.-]*[a-zA-Z0-9])?)|(?<![\p{L}\p{N}_#])#([\p{L}\p{N}_]{1,64})(?![\p{L}\p{N}_])/gu)){p.append(document.createTextNode(text.slice(last,m.index)));const link=el('button','mention-link',m[2]?m[0]:'@'+displayHandle(m[1]));link.onclick=m[2]?()=>{location.hash='tag='+encodeURIComponent(m[2].toLowerCase());}:async()=>{try{const data=await api('profile?handle='+encodeURIComponent(m[1]));openProfile(data.actor.id);}catch(e){toast(e.message);}};p.append(link);last=m.index+m[0].length;}p.append(document.createTextNode(text.slice(last)));return p;}
let threadConversation=[],threadCursor=null;
async function loadThread(uri,older=false){try{if(!older||currentThread!==uri){threadConversation=[];threadCursor=null;}currentThread=uri;const data=await api('thread?uri='+encodeURIComponent(uri)+(older&&threadCursor!==null?'&cursor='+threadCursor:''));threadCursor=data.conversationCursor;threadConversation=older?[...threadConversation,...(data.conversation||data.replies).filter(p=>!threadConversation.some(o=>o.uri===p.uri))]:(data.conversation||data.replies);view('thread');$('#page-label').textContent='Conversation';const container=$('#thread-content');container.replaceChildren();const root=data.root||data.post;container.append(renderPost(root));const replyNow=el('button','primary thread-reply','Reply to '+(data.post.uri===root.uri?'original post':'selected reply'));replyNow.onclick=()=>setReply(data.post);if(!data.post.deleted)container.append(replyNow);container.append(el('h3','thread-subtitle','Conversation · '+data.totalReplies+' replies'));const rows=threadConversation;const seen=new Set([root.uri]);function branch(parent,depth){for(const p of rows.filter(p=>p.parent===parent)){if(seen.has(p.uri))continue;seen.add(p.uri);const wrap=el('div','thread-branch'+(p.uri===uri?' selected-reply':''));wrap.style.setProperty('--depth',Math.min(depth,3));wrap.append(renderPost(p));container.append(wrap);branch(p.uri,depth+1);}}branch(root.uri,0);for(const p of rows){if(!seen.has(p.uri)){seen.add(p.uri);container.append(renderPost(p));}}if(!rows.length)container.append(el('div','empty','No replies yet. Start the conversation.'));if(threadCursor!==null&&threadCursor!==undefined){const more=el('button','secondary full','More replies');more.onclick=async()=>{more.disabled=true;await loadThread(uri,true);};container.append(more);}}catch(e){toast(e.message);}}
$('#thread-back').onclick=closeThread;
$('#thread-minimize').onclick=()=>{const collapsed=$('#thread-view').classList.toggle('makk-minimized');$('#thread-minimize').setAttribute('aria-expanded',String(!collapsed));$('#thread-minimize').setAttribute('aria-label',collapsed?'Restore conversation':'Minimize conversation');};
$('#thread-maximize').onclick=()=>{const maximized=$('#thread-view').classList.toggle('makk-maximized');$('#thread-view').classList.remove('makk-minimized');$('#thread-minimize').setAttribute('aria-expanded','true');$('#thread-maximize').setAttribute('aria-pressed',String(maximized));};
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.view==='thread'&&!document.querySelector('dialog[open]')&&!mobileSurfaces.size){event.preventDefault();closeThread();}});
function editPost(p){editingPost=p;$('#edit-post-form').elements.text.value=p.text;$('#edit-post-error').textContent='';$('#edit-post-dialog').showModal();}
$('#edit-post-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('posts/edit',{uri:editingPost.uri,text:e.target.elements.text.value});$('#edit-post-dialog').close();await refreshCurrent();toast('Post updated.');}catch(e){$('#edit-post-error').textContent=e.message;}finally{button.disabled=false;}};
function deletePost(p){deletingPost=p;$('#delete-post-dialog').showModal();}
$('#delete-post-confirm').onclick=async e=>{e.target.disabled=true;try{await api('posts/delete',{uri:deletingPost.uri});$('#delete-post-dialog').close();await refreshCurrent();toast('Post deleted.');}catch(e){toast(e.message);}finally{e.target.disabled=false;}};
async function refreshCurrent(){if(['communities','community'].includes(state.view))await loadCommunitiesRoute(location.hash.slice(1));else if(state.view==='profile')await loadProfilePosts();else if(state.view==='thread')await loadThread(currentThread);else if(state.view==='hashtags')await loadHashtags();else await loadFeed();}
async function loadNotificationCount(){if(!state.me){$('#notification-count').textContent='';return;}try{const data=await api('notifications');$('#notification-count').textContent=data.unread||'';const mobile=$('#mobile-notification-count');if(mobile)mobile.textContent=data.unread||'';}catch{}}
let notificationCursor=null,notificationLoading=false;
async function loadNotifications(older=false){if(notificationLoading)return;notificationLoading=true;const panel=$('#notifications-content');if(!older)panel.replaceChildren();panel.querySelector('#notification-more')?.remove();if(!state.me){panel.append(el('div','empty','Sign in to see your notifications.'));const signin=el('button','primary','Sign in');signin.onclick=()=>openAuth(false);panel.append(signin);notificationLoading=false;return;}try{const data=await api('notifications'+(older&&notificationCursor?'?before='+notificationCursor:''));notificationCursor=data.cursor;if(!older)latestNotification=data.notifications[0]?.id||0;if(!data.notifications.length)panel.append(el('div','empty','You’re all caught up.'));for(const n of data.notifications){const row=el('article','notification-card'+(n.seen?'':' unread'));const open=el('button','notification-open');open.append(avatar(n.sender,true));const copy=el('div');copy.append(el('b','',n.sender.name),el('p','',({dating_request:'sent you an Makk Dating request',dating_match:'accepted your Dating request — it’s a match',dating_message:'sent you a Dating message',message:'sent you a direct message',reply:'replied to your post',mention:'mentioned you',like:'liked your post',follow:'added you as a friend',repost:'reposted your post',quote:'quoted your post'})[n.type]),el('small','',ago(n.created)));open.append(copy);const mark=async()=>{await api('notifications/read',{id:n.id});row.classList.remove('unread');loadNotificationCount();};open.onclick=async()=>{try{await mark();if(n.type==='message')startMessage(n.sender.id);else if(n.type.startsWith('dating_'))location.hash='dating-chat='+n.message;else if(n.post)openThread(n.post);else openProfile(n.sender.id);}catch(e){toast(e.message);}};row.append(open);if(n.postDetails){row.append(el('p','notification-preview',n.postDetails.text));const actions=el('div','notification-actions');const thread=el('button','secondary','View thread');thread.onclick=()=>openThread(n.post);actions.append(thread);if(!n.postDetails.deleted){const reply=el('button','primary','Reply');reply.onclick=async()=>{try{await mark();await loadThread(n.post);location.hash='thread='+encodeURIComponent(n.post);setReply(n.postDetails);}catch(e){toast(e.message);}};actions.append(reply);}row.append(actions);}panel.append(row);}if(notificationCursor){const more=el('button','secondary full','Earlier notifications');more.id='notification-more';more.onclick=()=>loadNotifications(true);panel.append(more);}loadNotificationCount();}catch(e){toast(e.message);}finally{notificationLoading=false;}}
$('#notifications-read').onclick=async()=>{if(!requireMe())return;try{await api('notifications/read',{through:latestNotification});await loadNotifications();}catch(e){toast(e.message);}};setInterval(()=>{loadNotificationCount();loadMessageCount();if(state.view==='messages')loadMessages();if(state.view==='dating'&&(location.hash==='#dating-inbox'||location.hash.startsWith('#dating-chat=')&&!$('.dating-chat-form')))loadDatingRoute(location.hash.slice(1));},15000);

