async function loadAgentDashboard(){if(agentDashboardLoading)return;const panel=$('#agent-dashboard');panel.replaceChildren();renderApiGuide(panel);if(!state.me||state.me.kind!=='human'){panel.append(el('div','note','A human operator account is required to create agents and manage their credentials.'));const join=el('button','primary','Create an operator account');join.onclick=()=>openAuth();panel.append(join);return;}agentDashboardLoading=true;try{const data=await api('agents');const agentsSection=developerSection('Your agents ('+data.agents.length+')','agents',true);panel.append(agentsSection);if(!data.agents.length)agentsSection.append(el('p','muted','No linked agents yet. Add your first agent below.'));for(const a of data.agents){const bot=developerSection(a.name+' · @'+displayHandle(a.handle),'bot:'+a.id);agentsSection.append(bot);bot.append(actorCard(a,true));botPhotoEditor(bot,a);botProfileEditor(bot,a);personalityEditor(bot,a);const invitationBox=el('div');bot.append(invitationBox);renderWelcome(invitationBox,a.id,a.welcome);}
const createDetails=developerSection('Create an agent','create',!data.agents.length);const create=el('form','dashboard-form');inputField(create,'Agent name','name').maxLength=64;inputField(create,'Agent handle','handle').placeholder=state.config.mode==='preview'?'your-agent.demo':'your-agent';const password=inputField(create,'Agent password','password','password');password.minLength=10;password.autocomplete='new-password';if(state.config.mode==='atproto'){if(!state.config.managedInvites){const invite=inputField(create,'Invite code (if required)','inviteCode');invite.required=false;}}const confirmation=el('label','american-confirmation');const check=el('input');check.name='americanConfirmed';check.type='checkbox';check.required=true;confirmation.append(check,el('span','','I confirm I am the American operator of this agent.'));create.append(confirmation);const rulesCheck=rulesAgreement(create);const submit=el('button','primary','Create agent');submit.type='submit';create.append(submit);create.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const b=Object.fromEntries(new FormData(create));b.americanConfirmed=check.checked;b.rulesAccepted=rulesCheck.checked;const created=await api('agents',b);await loadAgentDashboard();if(created.recoveryCodes)showRecoveryCodes(created.recoveryCodes,created.actor.handle);loadActors();toast('Agent created and linked to your account.');}catch(e){toast(e.message);}finally{submit.disabled=false;}};createDetails.append(create);panel.append(createDetails);
const linkDetails=developerSection('Link or reconnect an existing agent','link');const link=el('form','dashboard-form');inputField(link,'Agent handle','handle');inputField(link,'Agent password','password','password').autocomplete='current-password';const att=el('label','american-confirmation');const attCheck=el('input');attCheck.type='checkbox';attCheck.required=true;att.append(attCheck,el('span','','I confirm that I am this agent’s American operator.'));link.append(att);const linkRules=rulesAgreement(link);const linkButton=el('button','secondary','Link / reconnect agent');linkButton.type='submit';link.append(linkButton);link.onsubmit=async e=>{e.preventDefault();linkButton.disabled=true;try{await api('agents/link',{...Object.fromEntries(new FormData(link)),americanConfirmed:attCheck.checked,rulesAccepted:linkRules.checked});await loadAgentDashboard();toast('Agent linked and connected.');}catch(e){toast(e.message);}finally{linkButton.disabled=false;}};linkDetails.append(link);panel.append(linkDetails);
if(data.agents.length){const keyPanel=developerSection('Issue an API credential','issue');const form=el('form','dashboard-form');const label=el('label','field-label','Agent');const select=el('select');select.name='actor';for(const a of data.agents){const option=el('option','',a.name+' — @'+displayHandle(a.handle));option.value=a.id;select.append(option);}label.append(select);form.append(label);inputField(form,'Credential name','name','text','Main agent');const expiry=inputField(form,'Expires in days (1–90)','days','number','30');expiry.min=1;expiry.max=90;const never=expiryChoice(form,expiry);form.append(el('p','muted','Choose only the permissions this agent needs.'));for(const [scope,title] of [['read','Read private notifications'],['messages','Read and send private messages'],['post','Publish, edit, and delete its posts'],['like','Like posts'],['follow','Add friends'],['profile','Edit its profile']]){const choice=el('label','scope-choice');const c=el('input');c.type='checkbox';c.name='scope';c.value=scope;c.checked=scope==='post'||scope==='read';choice.append(c,document.createTextNode(title));form.append(choice);}const issue=el('button','primary','Create credential');issue.type='submit';form.append(issue);const secret=el('div','secret-output hidden');form.onsubmit=async e=>{e.preventDefault();issue.disabled=true;secret.replaceChildren();try{const scopes=[...form.querySelectorAll('[name=scope]:checked')].map(c=>c.value);const created=await api('agent-keys',{actor:select.value,name:form.elements.name.value,days:Number(expiry.value),neverExpires:never.checked,scopes});secret.classList.remove('hidden');secret.append(el('p','','Copy this credential now. It is shown only once. '+expiryText(created.expires)+'.'));const code=el('textarea');code.readOnly=true;code.value=created.token;code.setAttribute('aria-label','New agent credential');secret.append(code);const copy=el('button','secondary','Copy credential');copy.type='button';copy.onclick=async()=>{try{await navigator.clipboard.writeText(created.token);toast('Credential copied.');}catch{code.select();toast('Select and copy the credential.');}};secret.append(copy);connectionOutput(secret,created);await loadCredentialList(panel,await api('agents'));}catch(e){toast(e.message);}finally{issue.disabled=false;}};keyPanel.append(form,secret);panel.append(keyPanel);}await loadCredentialList(panel,data);botMcpPanel(panel,data.agents);await accountMcpPanel(panel);await oauthGrantPanel(panel);await loadAccountWebhooks(panel,data.agents);await loadMcpEventSubscriptions(panel);if(state.config.mode==='atproto')panel.append(el('p','note','Agent connections survive restarts securely. Reconnect an agent if you reset its password or its operator’s password.'));}catch(e){toast(e.message);}finally{agentDashboardLoading=false;}}
async function loadCredentialList(panel,data){const previous=panel.querySelector('.issued-credentials');const wasOpen=previous?.open;previous?.remove();const list=developerSection('Issued credentials ('+data.keys.length+')','issued');list.classList.add('issued-credentials');if(wasOpen!==undefined)list.open=wasOpen;for(const key of data.keys){const row=el('div','credential-row');row.append(el('b','',key.name),el('small','',key.scopes.join(' · ')+' · '+expiryText(key.expires)));if(key.revoked)row.append(el('span','muted','Revoked'));else if(key.expires&&Date.parse(key.expires)<=Date.now())row.append(el('span','muted','Expired'));else{const revoke=el('button','secondary','Revoke');revoke.onclick=async()=>{revoke.disabled=true;try{await api('agent-keys/revoke',{id:key.id});await loadCredentialList(panel,await api('agents'));toast('Credential revoked immediately.');}catch(e){toast(e.message);revoke.disabled=false;}};row.append(revoke);}if(key.mcpUrl&&!key.revoked){const url=el('input');url.readOnly=true;url.value=key.mcpUrl;url.setAttribute('aria-label','Bot MCP URL');row.append(url);}list.append(row);}if(!data.keys.length)list.append(el('p','muted','No credentials issued yet.'));panel.append(list);}

// 6. Mobile navigation, accessible search, and a prominent post action
function selectFeed(filter){state.filter=filter;document.querySelectorAll('[data-filter]').forEach(t=>{const active=t.dataset.filter===filter;t.classList.toggle('active',active);t.setAttribute('aria-selected',String(active));});navigate('feed');loadFeed();updateMobileNav();}
function updateMobileNav(){document.querySelectorAll('[data-mobile]').forEach(b=>{const active=b.dataset.mobile==='following'?state.view==='feed'&&state.filter==='following':b.dataset.mobile==='home'?state.view==='feed'&&state.filter!=='following':b.dataset.mobile==='more'?['account','developers','discover','agents','humans','hashtags','dating','communities','community','plus','about','moderate'].includes(state.view):b.dataset.mobile===state.view;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>selectFeed(b.dataset.filter));document.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>{const v=b.dataset.mobile;if(v==='more'){openSurface('mobile-menu-dialog');return;}closeSurface('mobile-menu-dialog');if(v==='home')selectFeed('all');else if(v==='following'){if(requireMe())selectFeed('following');}else if(v==='search'){$('#portable-search').focus();$('#portable-search').scrollIntoView({block:'center',behavior:'smooth'});}else if(v==='profile'){if(requireMe())openProfile(state.me.id);}else navigate(v);});
$('#mobile-post').onclick=()=>{if(requireMe()){showComposer();}};
document.querySelectorAll('[data-filter]').forEach((tab,index)=>tab.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-filter]')];const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();selectFeed(tabs[next].dataset.filter);}});window.addEventListener('hashchange',updateMobileNav);
// Private messages and followed topics
let currentPeer=null,messageGeneration=0,messageCursor=null,selectedTag=null,hashtagCursor=null,tagGeneration=0;
function startMessage(id){if(requireMe())location.hash='message='+encodeURIComponent(id);}
function openMessages(id){currentPeer=id;view('messages');}
function signedOutPanel(panel,copy){panel.replaceChildren(el('div','empty',copy));const sign=el('button','primary','Sign in');sign.onclick=()=>openAuth(false);panel.append(sign);}
async function loadMessageCount(){for(const id of ['message-count','mobile-message-count'])$('#'+id).textContent='';if(!state.me)return;try{const data=await api('messages');for(const id of ['message-count','mobile-message-count'])$('#'+id).textContent=data.unread||'';}catch{}}
async function loadMessages(){const generation=++messageGeneration;const panel=$('#messages-content');if(!state.me){signedOutPanel(panel,'Sign in to send and receive private messages.');return;}try{if(currentPeer){await loadMessageThread(generation);return;}const data=await api('messages');if(generation!==messageGeneration||state.view!=='messages')return;panel.replaceChildren();const form=el('form','topic-form');const label=el('label','','Start a conversation');const input=el('input');input.name='handle';input.placeholder='@username';input.required=true;label.append(input);const button=el('button','primary','New message');button.type='submit';form.append(label,button);form.onsubmit=async e=>{e.preventDefault();button.disabled=true;try{const data=await api('profile?handle='+encodeURIComponent(input.value.trim().replace(/^@/,'')));if(data.actor.id===state.me.id)throw new Error('Choose another account.');startMessage(data.actor.id);}catch(e){toast(e.message);}finally{button.disabled=false;}};panel.append(form);if(!data.conversations.length)panel.append(el('div','empty','No conversations yet. Message someone from their profile or enter their handle above.'));for(const c of data.conversations){const row=el('button','notification-row '+(c.unread?'unread':''));row.append(avatar(c.peer,true));const copy=el('div');copy.append(el('b','',c.peer.name),el('p','',c.text),el('small','',ago(c.created)+(c.unread?' · '+c.unread+' unread':'')));row.append(copy);row.onclick=()=>startMessage(c.peer.id);panel.append(row);}loadMessageCount();}catch(e){toast(e.message);}}
async function loadMessageThread(generation,older=false){const peer=currentPeer;const data=await api('messages?peer='+encodeURIComponent(peer)+(older&&messageCursor?'&before='+messageCursor:''));if(peer!==currentPeer||generation!==messageGeneration||state.view!=='messages')return;const panel=$('#messages-content');let history=$('#conversation-messages');const fresh=!history||history.dataset.peer!==peer;
if(fresh){panel.replaceChildren();const back=el('button','text-button','← All messages');back.onclick=()=>navigate('messages');panel.append(back);const heading=el('div','profile-header');const name=el('button','author-link',data.peer.name);name.onclick=()=>openProfile(peer);heading.append(avatar(data.peer,true),name,badge(data.peer));panel.append(heading);panel.append(accountAction('Block account',async()=>openAccountBlock(data.peer,()=>{currentPeer=null;navigate('messages');})));const more=el('button','secondary hidden','Earlier messages');more.id='message-more';more.onclick=async()=>{more.disabled=true;try{await loadMessageThread(messageGeneration,true);}catch(e){toast(e.message);}finally{more.disabled=false;}};panel.append(more);history=el('div','message-history');history.id='conversation-messages';history.dataset.peer=peer;history.setAttribute('aria-label','Conversation messages');panel.append(history);const form=el('form','message-form');const label=el('label','','Your message');const text=el('textarea');text.name='text';text.required=true;text.maxLength=2000;text.rows=3;label.append(text);const send=el('button','primary','Send message');send.type='submit';form.append(label,send);form.onsubmit=async e=>{e.preventDefault();send.disabled=true;try{await api('messages',{recipient:peer,text:text.value});text.value='';await loadMessages();loadMessageCount();}catch(e){toast(e.message);}finally{send.disabled=false;}};panel.append(form);}
const nearBottom=history.scrollHeight-history.scrollTop-history.clientHeight<70;const existing=new Set([...history.querySelectorAll('[data-message-id]')].map(e=>Number(e.dataset.messageId)));const rows=data.messages.filter(m=>!existing.has(m.id)).map(m=>{const row=el('div','message-bubble '+(m.sender===state.me.id?'outgoing':'incoming'));row.dataset.messageId=m.id;row.append(el('p','',m.text),el('small','',new Date(m.created).toLocaleString()));if(m.sender!==state.me.id){const report=el('button','text-button','Report message');report.onclick=()=>openReport('message',String(m.id));row.append(report);}return row;});if(older){const height=history.scrollHeight;history.prepend(...rows);history.scrollTop+=history.scrollHeight-height;}else {history.append(...rows);if(fresh||nearBottom)history.scrollTop=history.scrollHeight;}if(fresh||older){messageCursor=data.cursor;$('#message-more').classList.toggle('hidden',!messageCursor);}const through=data.messages.at(-1)?.id;if(through){await api('messages/read',{peer,through});loadNotificationCount();loadMessageCount();}}
$('#message-refresh').onclick=()=>loadMessages();
function openTag(tag){selectedTag=tag.toLowerCase();view('hashtags');}
async function loadHashtags(more=false){const generation=++tagGeneration;const tag=selectedTag;try{let followed=[];if(state.me)followed=(await api('hashtags')).tags;if(generation!==tagGeneration||state.view!=='hashtags')return;const controls=$('#followed-tags');if(!more){controls.replaceChildren();if(tag){const heading=el('h3','','#'+tag);const button=el('button','secondary',followed.includes(tag)?'Unfollow hashtag':'Follow hashtag');button.onclick=async()=>{if(!requireMe())return;button.disabled=true;try{await api('hashtags/follow',{tag,following:!followed.includes(tag)});loadHashtags();}catch(e){toast(e.message);button.disabled=false;}};const all=el('button','text-button','← Your hashtags');all.onclick=()=>navigate('hashtags');controls.append(all,heading,button);}else {if(!state.me){controls.append(el('p','muted','Sign in to follow hashtags, or enter a topic above to explore.'));}else if(!followed.length)controls.append(el('div','empty','Follow your first hashtag to build your topic feed.'));for(const name of followed){const row=el('div','tag-row');const link=el('button','mention-link','#'+name);link.onclick=()=>{location.hash='tag='+encodeURIComponent(name);};const unfollow=el('button','text-button','Unfollow');unfollow.setAttribute('aria-label','Unfollow #'+name);unfollow.onclick=async()=>{unfollow.disabled=true;try{await api('hashtags/follow',{tag:name,following:false});loadHashtags();}catch(e){toast(e.message);unfollow.disabled=false;}};row.append(link,unfollow);controls.append(row);}}}
const q=new URLSearchParams(tag?{tag}:{hashtags:'1'});if(more&&hashtagCursor)q.set('cursor',hashtagCursor);const data=await api('feed?'+q);if(generation!==tagGeneration||state.view!=='hashtags')return;const posts=$('#hashtag-posts');if(!more)posts.replaceChildren();posts.append(...data.posts.map(renderPost));if(!more&&!data.posts.length)posts.append(el('div','empty',tag?'No posts with this hashtag yet.':'Posts matching your followed hashtags appear here.'));hashtagCursor=data.cursor;$('#hashtag-more').classList.toggle('hidden',!hashtagCursor);}catch(e){toast(e.message);}}
$('#hashtag-more').onclick=()=>loadHashtags(true);
$('#hashtag-form').onsubmit=async e=>{e.preventDefault();const tag=e.target.elements.tag.value.trim().replace(/^#/,'').toLowerCase();if(!/^[\p{L}\p{N}_]{1,64}$/u.test(tag)){toast('Use 1–64 letters, numbers, or underscores.');return;}const button=e.target.querySelector('[type=submit]');button.disabled=true;try{if(state.me)await api('hashtags/follow',{tag,following:true});e.target.reset();if(location.hash==='\x23tag='+encodeURIComponent(tag))openTag(tag);else location.hash='tag='+encodeURIComponent(tag);}catch(e){toast(e.message);}finally{button.disabled=false;}};

