let sharePost=null,shareFile=null,shareGeneration=0;
async function openShare(post){const generation=++shareGeneration;sharePost=post;shareFile=null;$('#share-status').textContent='Preparing your post image…';$('#share-link').value=location.origin+'/post/'+encodeURIComponent(post.uri);const imageUrl='/share-image?uri='+encodeURIComponent(post.uri);$('#share-preview').src=imageUrl;$('#share-save').href=imageUrl+'&download=1';$('#share-file').disabled=true;openSurface('share-dialog');try{const r=await fetch(imageUrl);if(!r.ok){const error=await r.json();throw Error(error.error||'Could not prepare image.');}const blob=await r.blob();if(generation!==shareGeneration)return;shareFile=new File([blob],'amerika-social-post.png',{type:'image/png'});$('#share-file').disabled=!(navigator.canShare&&navigator.canShare({files:[shareFile]}));$('#share-status').textContent='On iPhone, hold the preview to save it to Photos, or use Share image. Save image also downloads a PNG.';}catch(e){if(generation===shareGeneration)$('#share-status').textContent=e.message;}}
$('#share-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#share-link').value);toast('Post link copied.');}catch{$('#share-link').select();toast('Select and copy the post link.');}};
$('#share-native').onclick=async()=>{try{if(navigator.share)await navigator.share({title:'Post on Makk Social',url:$('#share-link').value});else $('#share-copy').click();}catch(e){if(e.name!=='AbortError')toast(e.message);}};
$('#share-file').onclick=async()=>{if(!shareFile)return;try{await navigator.share({files:[shareFile],title:'Makk Social post'});}catch(e){if(e.name!=='AbortError')toast('Use Save image or hold the preview to save it.');}};
$('#share-embed').onclick=async()=>{const code='<iframe src="'+location.origin+'/embed?uri='+encodeURIComponent(sharePost.uri)+'" width="550" height="550" title="Makk Social post" loading="lazy" style="max-width:100%;border:0" sandbox="allow-popups allow-popups-to-escape-sandbox allow-same-origin"></iframe>';$('#share-embed-code').value=code;$('#share-embed-code').classList.remove('hidden');try{await navigator.clipboard.writeText(code);toast('Embed code copied.');}catch{$('#share-embed-code').select();}};
$('#share-dialog').addEventListener('close',()=>{shareGeneration++;shareFile=null;sharePost=null;$('#share-embed-code').value='';$('#share-embed-code').classList.add('hidden');$('#share-preview').removeAttribute('src');});

