document.querySelectorAll('[data-icon]').forEach(n=>n.replaceChildren(icon(n.dataset.icon)));
$('#desktop-profile').onclick=()=>{if(requireMe())openProfile(state.me.id);};
$('#desktop-friends').onclick=()=>{if(requireMe())selectFeed('following');};
function updateDesktopSelection(){const friends=state.view==='feed'&&state.filter==='following';$('#desktop-friends').classList.toggle('active',friends);$('#desktop-profile').classList.toggle('active',state.view==='profile'&&currentProfile?.id===state.me?.id);document.querySelector('.desktop-navigation [data-view=feed]').classList.toggle('active',state.view==='feed'&&!friends);for(const n of document.querySelectorAll('.desktop-navigation .nav-item')){if(n.classList.contains('active'))n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');}}
const originalDesktopView=view;view=function(...args){originalDesktopView(...args);updateDesktopSelection();};
